def process_pattern_scan(runner, lane):
    """Use the governed pattern job path without replacing the live-call loop."""
    policy = runner._policy()
    lane.enabled = policy.active and policy.valid and policy.allows("patterns")
    if not lane.enabled:
        lane.discovery = "disabled_or_policy_hold"
        lane.discovery_error_code = None
        lane.last_result = "disabled_or_policy_hold"
        return False

    from ai_worker.patterns import discover
    summary = {}
    try:
        runner.discover_if_due("pattern_review", lambda: discover(runner), summary)
        lane.discovery_error_code = None
    except AIError as error:
        # Candidate discovery and an already leased/pending job are separate.
        # Keep the latter moving through the gateway's fresh policy fence.
        summary["pattern_discovery"] = "error"
        lane.discovery_error_code = error.code
    lane.discovery = summary.get("pattern_discovery", "unavailable")
    jobs = runner.bridge.claim_jobs(["pattern_review"])
    if not jobs:
        lane.last_result = "discovery_error" if lane.discovery_error_code else "no_pattern_job"
        return False

    # A heartbeat transport failure must not abandon an already claimed lease.
    try:
        runner.heartbeat("working", details={"mode": "pattern_review", "pattern_discovery": lane.discovery})
    except AIError as error:
        print("Pattern heartbeat deferred: " + safe_error(error), flush=True)
    runner.process_claimed(jobs[0], None, summary)
    lane.last_result = summary.get("status", "processed")
    if lane.last_result == "pattern_scan_saved":
        runner.last_success = datetime.now(timezone.utc).isoformat()
    print(json.dumps({key: summary[key] for key in ("status", "pattern_accounts_scanned", "pattern_draft_flags")
                      if key in summary}), flush=True)
    return True


class PatternLane:
    """Give one scan a turn after bounded live work, or before older backlog."""

    def __init__(self):
        self.priority_jobs = 0
        self.next_at = 0.0
        self.enabled = None
        self.discovery = "not_checked"
        self.discovery_error_code = None
        self.last_result = "not_checked"

    def after_priority(self, runner):
        self.priority_jobs = min(PATTERN_PRIORITY_BURST, self.priority_jobs + 1)
        return self._turn(runner, idle=False)

    def during_idle(self, runner):
        return self._turn(runner, idle=True)

    def _turn(self, runner, *, idle):
        now = monotonic()
        if now < self.next_at or not idle and self.priority_jobs < PATTERN_PRIORITY_BURST:
            return False
        # One scan follows eight completed priority jobs, including booked QA.
        self.priority_jobs = 0
        try:
            return process_pattern_scan(runner, self)
        except AIError:
            self.last_result = "error"
            raise
        finally:
            self.next_at = monotonic() + PATTERN_TURN_INTERVAL_SECONDS

    def details(self):
        return {"pattern_pipeline_enabled": self.enabled, "pattern_discovery": self.discovery,
                "pattern_discovery_error_code": self.discovery_error_code,
                "pattern_last_result": self.last_result}
